const chatId = msg.payload.chatId;
const senderId = String((msg.originalMessage && msg.originalMessage.from && msg.originalMessage.from.id) || chatId);
const body = String(msg.payload.content || '').trim();
const allowed = (env.get('AUTHORIZED_TELEGRAM_IDS') || '').split(',').map(s => s.trim()).filter(Boolean);

function reply(text) {
    return { payload: { chatId: chatId, type: 'message', content: text } };
}

if (!allowed.includes(senderId)) {
    node.warn(`unauthorised sender: ${senderId}`);
    return [null, reply(`Sorry, this account is not authorised to control the kiosks. (Your Telegram id is ${senderId} - add it to AUTHORIZED_TELEGRAM_IDS if this is you.)`), null];
}

flow.set('last_chat', chatId);
const pending = flow.get('pending');
const fresh = pending && (Date.now() - pending.ts) < 300000;

if (/^confirm$/i.test(body)) {
    if (fresh) {
        flow.set('pending', null);
        msg.profile = pending.profile;
        const out = reply(`Deploying the ${pending.label} profile now - you will get a message when it is done.`);
        msg.ack = out.payload;
        return [null, out, msg];
    }
    return [null, reply('Nothing is waiting for confirmation.'), null];
}

// base64 for the shell boundary: raw text never reaches a command line
msg.chatId = chatId;
msg.payload = Buffer.from(senderId).toString('base64') + ' ' + Buffer.from(body).toString('base64');
return [msg, null, null];

const PROFILES = { 'bett-london': 'Bett London', 'tech-awards': 'Tech Awards', 'bett-brasil': 'Bett Brasil' };
const chatId = flow.get('last_chat');
let intent;
try { intent = JSON.parse(msg.payload); } catch (e) { intent = null; }
function reply(text) {
    msg.payload = { chatId: chatId, type: 'message', content: text };
    return msg;
}
if (!intent || !['deploy_profile', 'status', 'reject'].includes(intent.action)) {
    return reply('Sorry - I could not understand that as a kiosk request.');
}
if (intent.action === 'deploy_profile' && PROFILES[intent.profile]) {
    flow.set('pending', { profile: intent.profile, label: PROFILES[intent.profile], ts: Date.now() });
    return reply(`Deploy the ${PROFILES[intent.profile]} profile to the event kiosks? Reply CONFIRM.`);
}
if (intent.action === 'status') {
    return reply('Deployments are live. Status reporting arrives with the kiosk health feed.');
}
return reply('I can only switch the kiosks between the approved event profiles (Bett London, Tech Awards, Bett Brasil).');

const APPROVED = ['bett-london', 'tech-awards', 'bett-brasil'];
if (!APPROVED.includes(msg.profile)) { node.error('profile not approved: ' + msg.profile); return null; }
msg.payload = msg.profile;  // enum-validated token, safe to append
return msg;

// Runs for stdout and return-code outputs; act once, on the stdout payload.
if (typeof msg.payload !== 'string' || !msg.payload.includes('run_finished')) { return null; }
let result = null;
for (const line of msg.payload.split('\n')) {
    try { const evt = JSON.parse(line); if (evt.event === 'run_finished') result = evt; } catch (e) { /* not json */ }
}
if (!result) { return null; }
const PROFILES = { 'bett-london': 'Bett London', 'tech-awards': 'Tech Awards', 'bett-brasil': 'Bett Brasil' };
const label = PROFILES[result.profile] || result.profile;
let text;
if (result.ok) {
    text = `Deployment complete. ${result.hosts_succeeded} of ${result.hosts_total} kiosks are online and running the ${label} profile.`;
} else if (!result.hosts_total) {
    text = 'Deployment did not run: no kiosks matched the inventory. (Is the kiosk machine set up and listed in inventory.ini?)';
} else {
    text = `Deployment FAILED - the kiosks rolled back to the previous version. (${result.hosts_succeeded} of ${result.hosts_total} healthy.)`;
}
msg.payload = { chatId: flow.get('last_chat'), type: 'message', content: text };
return msg;
